insert into srm_eval_band (comp_cd, tmpl_id, item_id, upper_ppm, score_pct, created_by, updated_by)
select hb_current_comp(), #{tmplId}, i.item_id, #{f.upperPpm}, #{f.scorePct}, #{by}, #{by}
  from srm_eval_item i where i.tmpl_id = #{tmplId} and i.item_no = #{itemNo}

insert into srm_eval_band (comp_cd, tmpl_id, item_id, upper_ppm, score_pct, created_by, updated_by)
select b.comp_cd, #{to}, n.item_id, b.upper_ppm, b.score_pct, #{by}, #{by}
  from srm_eval_band b
  join srm_eval_item o on o.item_id = b.item_id
  join srm_eval_item n on n.tmpl_id = #{to} and n.item_no = o.item_no
 where b.tmpl_id = #{from}

insert into srm_eval_item (comp_cd, tmpl_id, item_no, section_nm, item_nm, max_score, weight, fail_below, input_type, metric_cd,
                           guide, created_by, updated_by)
select comp_cd, #{to}, item_no, section_nm, item_nm, max_score, weight, fail_below, input_type, metric_cd, guide, #{by}, #{by}
  from srm_eval_item where tmpl_id = #{from}

mapper.update:
update srm_eval_tmpl
   set valid_to = #{validFrom}::date - 1, row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where tmpl_cd = #{tmplCd} and tmpl_id <> #{exceptId} and status = 'RELEASED' and valid_to is null
   and valid_from < #{validFrom}

update srm_eval_tmpl
   set status = 'RELEASED', released_by = #{by}, released_at = now(), row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where tmpl_id = #{id} and status = 'DRAFT' and row_ver = #{rowVer}

update srm_eval_tmpl
   set status = 'OBSOLETE', row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where tmpl_id = #{id} and status = #{from} and row_ver = #{rowVer}

mapper.select:
select c.cust_id, c.cust_cd, c.cust_nm, s.trade_status
  from srm_supplier s join mst_cust c on c.cust_id = s.cust_id
 where c.cust_cd = #{custCd}

mapper.sql:
 where e.period_to between #{c.from} and #{c.to}
and e.status = #{c.status}

   and (e.eval_no ilike #{c.keywordLike} escape '\' or c.cust_cd ilike #{c.keywordLike} escape '\' or c.cust_nm ilike #{c.keywordLike} escape '\')

mapper.update:
update srm_eval_score set score = #{score}, comment = #{comment}, updated_at = now(), updated_by = #{by}
 where eval_id = #{evalId} and item_id = #{itemId}
   and (score is distinct from #{score}::numeric or comment is distinct from #{comment}::varchar)

update srm_eval
   set status = 'CONFIRMED', total_score = #{total}, grade_cd = #{gradeCd}, fail_yn = #{failYn}, suggest_trade_status = #{suggest},
       confirmed_by = #{by}, confirmed_at = now(), row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where eval_id = #{id} and status = 'DRAFT' and row_ver = #{rowVer}

update srm_eval
   set status = 'CANCELLED', cancel_reason = #{reason}, row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where eval_id = #{id} and status = 'DRAFT' and row_ver = #{rowVer}

mapper.select:
select count(*) as issued_cnt,
       count(*) filter (where exists (select 1 from srm_po_ack a where a.po_id = r.po_id and a.rev = r.rev
                                         and a.ack_on <= (r.issued_at at time zone #{zone})::date + #{dueDays})) as on_time_cnt
  from srm_po_rev r join srm_po p on p.po_id = r.po_id
 where p.cust_id = #{custId}
   and (r.issued_at at time zone #{zone})::date between #{from} and #{to}
